    { id: 'C-012', name: 'Company B', email: 'b@example.com', country: 'BE', tier: 'standard' },
  ];
  const invoices = [
    { number: 'INV-2026-0001', customerId: 'c-012', issueDate: '2026-10-07', status: 'issued', lines: [] },
  ];
  const r = mergeCustomers(customers, invoices, 'C-012', 'c-001');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices[0].customerId, 'C-001');
});

test('mergeCustomers maintains order of remaining customers', () => {
  const customers = [
    { id: 'C-001', name: 'A', email: 'a@x.com', tier: 'gold' },
    { id: 'C-002', name: 'B', email: 'b@x.com', tier: 'standard' },
    { id: 'C-012', name: 'Duplicate', email: 'dup@x.com', tier: 'standard' },
    { id: 'C-003', name: 'C', email: 'c@x.com', tier: 'silver' },
  ];
  const r = mergeCustomers(customers, [], 'C-012', 'C-001');
  assert.equal(r.ok, true);
  assert.equal(r.value.customers.length, 3);
  assert.equal(r.value.customers[0].id, 'C-001');
  assert.equal(r.value.customers[1].id, 'C-002');
  assert.equal(r.value.customers[2].id, 'C-003');
});

test('mergeCustomers works with large invoice lists', () => {
  const customers = listCustomers();
  const invoices = Array.from({ length: 100 }, (_, i) => ({
    number: `INV-2026-${String(i + 1).padStart(4, '0')}`,
    customerId: i % 2 === 0 ? 'C-012' : 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [],
  }));
  const r = mergeCustomers(customers, invoices, 'C-012', 'C-001');
  assert.equal(r.ok, true);
  const c012Count = r.value.invoices.filter((inv) => inv.customerId === 'C-012').length;
  assert.equal(c012Count, 0);
  const c001Count = r.value.invoices.filter((inv) => inv.customerId === 'C-001').length;
  assert.equal(c001Count, 100);
});

test('mergeCustomers with invoices that have payments and vouchers', () => {
  const customers = listCustomers();
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-012',
      issueDate: '2026-10-07',
      status: 'partially_paid',
      lines: [],
      payments: [{ amount: 1000, date: '2026-10-10' }],
      voucher: { code: 'SAVE10', amount: 500 },
    },
  ];
  const r = mergeCustomers(customers, invoices, 'C-012', 'C-001');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices[0].customerId, 'C-001');
  assert.deepEqual(r.value.invoices[0].payments, [{ amount: 1000, date: '2026-10-10' }]);
  assert.deepEqual(r.value.invoices[0].voucher, { code: 'SAVE10', amount: 500 });
});

